            reward: { zh: '🏭 21 萬塊！好驚人的產量。小Q：「用萬當單位，再大的數字都不怕。走，去看看那本出事的帳本，它的位值好像被弄亂了。」',
                      en: '🏭 210,000! An astonishing output. Little Q: “With ten-thousand as a unit, no number is scary. Now, to that troubled ledger — its place values look scrambled.”' },
