          story: { zh: '小Q指著上游的高山：「水庫的水從哪來？高山上的雪是『固態』，天氣一暖就『融化』成液態的水，順著大漢溪流進水庫；水面的水又會『蒸發』成氣態的水蒸氣——這就是『水的三態』。今天融雪每小時流入 {12} 萬立方公尺，一連流了 {5} 小時，共流入幾萬立方公尺？」',
                   en: 'Little Q points at the peaks: “Where does the water come from? Mountain snow is SOLID; warmth MELTS it to liquid water that flows down the Dahan into the reservoir; surface water EVAPORATES to gaseous vapour — the THREE STATES OF WATER. Today snowmelt flows in at {12} ten-thousand m³ per hour for {5} hours — how many ten-thousand m³ in all?”' },
          clueNote: { zh: '水的三態：雪(固)→融化→水(液)。融雪 12 萬 × 5 小時＝流入 60 萬立方公尺', en: 'States: snow(solid)→melt→water(liquid). Inflow 12 × 5 = 60 ten-thousand m³' },
