      culprit: 'xi',
      accuse: { zh: '洩洪多了一截，三個人都說了自己知道的事。翻開證據板一條一條對——多洩的是「150 萬立方公尺」，那是你最後用實際 750 萬減計畫 600 萬才算出來、還沒說出口的，颱風夜控制室也沒人看到。可是有一個人，卻脫口說出「才多洩 150 萬立方公尺」……沒去多開閘門的人，怎麼會事先知道剛好多洩 150 萬？是誰？',
                en: 'The release ran over, and all three told what they know. Check the evidence line by line — “150 ten-thousand m³ excess” was computed by YOU last (actual 750 minus plan 600), still unspoken, unseen in the storm-night control room. Yet one person blurted “only 150 ten-thousand m³ over”… how could someone who never opened the extra gate know it was exactly 150? Who?' },
