      page: { id: 'temple-parade', emoji: '🏮', name: { zh: '故事書第 9 頁 · 普濟堂遶境', en: 'Storybook Page 9 · Temple Parade' } },
      intro: [
        { zh: '家鄉第九站——大溪普濟堂！一年一度最盛大的「大溪大拜拜」就要登場，這是關聖帝君的聖誕遶境，滿街紅燈籠、鑼鼓喧天，家家戶戶擺出香案，是家鄉一整年最熱鬧的日子。可是社頭伯台灣藍鵲阿聖急得直搓手：「偵探！遶境的路線圖被風吹亂了，各社頭到廟口的『時辰』全對不上——神轎要是沒準時到，這百年的老規矩就亂了套啊！」',
          en: 'Ninth stop of the hometown — Daxi Puji Temple! The grandest annual “Daxi Grand Parade” is about to begin — the birthday procession of Lord Guan, streets full of red lanterns, gongs and drums thundering, altars at every door: the hometown’s liveliest day of the year. But Ah-Sheng the Formosan blue magpie, the guild elder, wrings his hands: “Detective! The parade route blew into disarray, and the guilds’ arrival TIMES at each temple gate won’t match — if the palanquin isn’t punctual, this century-old custom falls apart!”' },
        { zh: '小Q跳上香案：「遶境最講究『準時、按路線』——用『時間』算時辰、用『方位』定路線、再用『速度』抓隊伍走多快，就能排得準準的。對了，滿街紅燈籠的『光』還有個小祕密呢。安安，我們把遶境的路線和時辰一筆一筆排好，順便查查——到底是誰動了路線。查案兼排陣，開始！」',
          en: 'Little Q hops onto an altar: “A parade is all about punctuality and route — use TIME for the hours, DIRECTION for the route, and SPEED for how fast the procession moves, and it all lines up. And those red lanterns hold a little secret of LIGHT. An-An, let’s set the route and hours entry by entry, and find who moved the route. Case and procession, begin!”' },
      ],
